function tryParse(s) {
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}
function extractBalancedObject(text) {
  let depth = 0, start = -1, inString = false, escape = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escape) {
        escape = false;
        continue;
      }
      if (ch === "\\") {
        escape = true;
        continue;
      }
      if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === "{") {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === "}") {
      depth--;
      if (depth === 0 && start !== -1) return text.slice(start, i + 1);
    }
  }
  return "";
}
function extractJson2(text) {
  if (!text) return { reply: "", needs_clarification: false, tool_calls: [] };
  const candidates = [text.trim()];
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) candidates.push(fenced[1].trim());
  const balanced = extractBalancedObject(text);
  if (balanced) candidates.push(balanced);
  for (const c of candidates) {
    if (!c) continue;
    let parsed = tryParse(c);
    if (parsed && typeof parsed === "object") return parsed;
    parsed = tryParse(repairJson(c));
    if (parsed && typeof parsed === "object") return parsed;
  }
  return { reply: text.trim(), needs_clarification: false, tool_calls: [] };
}
async function callAgentLlm(messages, { onDelta } = {}) {
  assertLlmKey();
  const url = llmUrl("/chat/completions");
  const res = await fetch(url, {
    method: "POST",
    headers: llmHeaders(),
    body: JSON.stringify({ model: AGENT_MODEL, messages, stream: true, max_tokens: 16e3 })
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw llmError(res.status, text);
  }
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let lineBuf = "";
  let content = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    lineBuf += decoder.decode(value, { stream: true });
    let idx;
    while ((idx = lineBuf.indexOf("\n")) >= 0) {
      const line = lineBuf.slice(0, idx).trim();
      lineBuf = lineBuf.slice(idx + 1);
      if (!line.startsWith("data:")) continue;
      const data = line.slice(5).trim();
      if (data === "[DONE]") break;
      try {
        const chunk = JSON.parse(data);
        const delta = chunk?.choices?.[0]?.delta?.content || "";
        if (delta) {
          content += delta;
          onDelta?.(delta);
        }
      } catch {
      }
    }
  }
  if (!content) throw new Error("Empty response from agent model");
  return extractJson2(content);
}
async function toolWebSearch({ query }) {
  if (!query?.trim()) throw new Error('web_search requires a "query" string');
  const q = query.trim();
  const upstream = await fetch(FIREWORKS_WEB_SEARCH_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query: q }),
    signal: AbortSignal.timeout(15e3)
  });
  if (!upstream.ok) {
    const text = await upstream.text().catch(() => "");
    throw new Error(`Search API ${upstream.status}: ${text.slice(0, 200)}`);
  }
  const json = await upstream.json();
  const results = Array.isArray(json?.results) ? json.results.slice(0, 6) : [];
  return { query: q, results };
}
