app.get("/api/generate-deck/job/:jobId", async (req, res) => {
  const { jobId } = req.params;
  let job;
  try {
    job = await getGenerationJob(jobId, req.user.id);
  } catch (e) {
    if (isDbError(e)) {
      return res.status(503).json({ error: "Database unavailable" });
    }
    return res.status(500).json({ error: "DB error" });
  }
  if (!job) return res.status(404).json({ error: "Job not found" });
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache, no-transform");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  res.flushHeaders?.();
  const send = (event, data) => {
    try {
      res.write(`event: ${event}
data: ${JSON.stringify(data)}

`);
    } catch {
    }
  };
  let closed = false;
  req.on("close", () => {
    closed = true;
  });
  let cursor = 0;
  const flush = (events) => {
    for (let i = cursor; i < events.length; i++) {
      if (closed) return;
      const { event, data } = events[i];
      send(event, data);
    }
    cursor = events.length;
  };
  flush(job.events || []);
  if (job.status === "completed" || job.status === "failed") {
    return res.end();
  }
  const ping = setInterval(() => {
    if (!closed) res.write(": ping\n\n");
  }, 15e3);
  const poll = async () => {
    if (closed) {
      clearInterval(ping);
      return;
    }
    try {
      const updated = await getGenerationJob(jobId, req.user.id);
      if (!updated) {
        clearInterval(ping);
        return res.end();
      }
      flush(updated.events || []);
      if (updated.status === "completed" || updated.status === "failed") {
        clearInterval(ping);
        return res.end();
      }
    } catch (e) {
      if (isDbError(e)) {
        clearInterval(ping);
        send("error", { error: "Database unavailable" });
        return res.end();
      }
      console.error("[job-sse] poll error:", e?.message);
    }
    if (!closed) setTimeout(poll, 350);
  };
  setTimeout(poll, 350);
});
